// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 amt) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(this));

        uint256 fund = bound(amt, 0, 1 ether);
        vm.deal(address(this), fund);
        (bool s, ) = address(c).call{value: fund}("");
        require(s);

        vm.deal(caller, 1 wei);

        bool ok;
        vm.prank(caller);
        try c.withdraw(fund) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
